(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.SessionRestoreModel=api})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';const KEY='ob.sessionRestore.v1';function fail(c){throw Object.assign(new Error(c),{code:c})}function id(v){if(typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,64}$/.test(v))fail('INVALID_ID');return v}function ids(list){if(!Array.isArray(list)||list.length>64)fail('INVALID_IDS');list=list.map(id);if(new Set(list).size!==list.length)fail('DUPLICATE_ID');return list}function url(v){if(v==='about:newtab')return v;if(typeof v!=='string'||v.length>2048||/[\x00-\x20\x7f]/.test(v))fail('INVALID_URL');let u;try{u=new URL(v)}catch(_){fail('INVALID_URL')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password)fail('INVALID_URL');return u.href}function prepare(s){if(s===null)return null;if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!['crash','closed'].includes(s.reason)||!Array.isArray(s.tabs)||s.tabs.length>64||!Number.isFinite(s.endedAt)||s.endedAt<0)fail('INVALID_SNAPSHOT');const out={version:1,id:id(s.id),revision:s.revision,reason:s.reason,endedAt:s.endedAt,tabs:[],blocked:0};const seen=new Set();for(const t of s.tabs){if(t?.private===true)continue;try{if(t?.private!==false||typeof t.title!=='string'||!t.title.trim()||t.title.length>160)fail('INVALID_TAB');const next={id:id(t.id),title:t.title,url:url(t.url)};if(seen.has(next.id))fail('DUPLICATE_ID');seen.add(next.id);out.tabs.push(next)}catch(_){out.blocked++}}return out}
function progress(p){if(!p||p.version!==1)fail('INVALID_PROGRESS');const out={version:1,snapshotId:id(p.snapshotId),completedIds:ids(p.completedIds),request:null};if(p.request!==null){out.request={id:id(p.request.id),tabIds:ids(p.request.tabIds),revision:p.request.revision};if(!Number.isSafeInteger(out.request.revision)||out.request.revision<0||!out.request.tabIds.length||out.request.tabIds.some(x=>out.completedIds.includes(x)))fail('INVALID_PROGRESS')}return out}function fresh(snapshotId){return{version:1,snapshotId:id(snapshotId),completedIds:[],request:null}}function load(storage){try{const raw=storage.getItem(KEY);if(raw===null)return null;if(raw.length>20000)fail('INVALID_PROGRESS');return progress(JSON.parse(raw))}catch(e){fail(e.code||'INVALID_PROGRESS')}}function save(storage,p){p=progress(p);try{storage.setItem(KEY,JSON.stringify(p))}catch(_){fail('STORAGE_FULL')}return p}
function begin(snapshot,p,selected,requestId){p=progress(p);if(p.snapshotId!==snapshot.id||p.request)fail('PENDING_RESTORE');selected=ids(selected);if(!selected.length||selected.some(x=>!snapshot.tabs.some(t=>t.id===x)||p.completedIds.includes(x)))fail('INVALID_SELECTION');return progress({...p,request:{id:id(requestId),tabIds:selected,revision:snapshot.revision}})}function finish(p,result){p=progress(p);if(!p.request||!result||!Array.isArray(result.failed))fail('INVALID_RESULT');const restored=ids(result.restoredIds),failed=ids(result.failed.map(x=>x.id));const all=[...restored,...failed];if(new Set(all).size!==all.length||all.length!==p.request.tabIds.length||all.some(x=>!p.request.tabIds.includes(x)))fail('INVALID_RESULT');return progress({...p,completedIds:[...p.completedIds,...restored],request:null})}return Object.freeze({KEY,prepare,progress,fresh,load,save,begin,finish});});
